import{_ as t,K as i,a as l,c as r,ac as a,b as s,q as p}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"中国象棋：开局原则与常见布局","description":"看懂中炮、屏风马和飞相的目的，用六步发展棋子，而不是机械背招。","frontmatter":{"title":"中国象棋：开局原则与常见布局","description":"看懂中炮、屏风马和飞相的目的，用六步发展棋子，而不是机械背招。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"棋类入门","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"中国象棋入门","summary":"看懂中炮、屏风马和飞相的目的，用六步发展棋子，而不是机械背招。","status":"active","related":[{"title":"中国象棋：棋盘、走法与胜负规则","link":"/life/personal/chess/xiangqi/rules","kind":"棋类入门","scope":"general","audience":"general"},{"title":"中国象棋：双车、重炮与马后炮","link":"/life/personal/chess/xiangqi/mates","kind":"棋类入门","scope":"general","audience":"general"},{"title":"中国象棋：漏看、失子与残局复盘","link":"/life/personal/chess/xiangqi/review","kind":"棋类入门","scope":"general","audience":"general"}],"prev":{"text":"中国象棋：双车、重炮与马后炮","link":"/life/personal/chess/xiangqi/mates"},"next":{"text":"中国象棋：漏看、失子与残局复盘","link":"/life/personal/chess/xiangqi/review"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"中国象棋：双车、重炮与马后炮","link":"/life/personal/chess/xiangqi/mates"},"next":{"text":"中国象棋：漏看、失子与残局复盘","link":"/life/personal/chess/xiangqi/review"}},"headers":[],"relativePath":"life/personal/chess/xiangqi/opening.md","filePath":"life/personal/chess/xiangqi/opening.md"}'),o={name:"life/personal/chess/xiangqi/opening.md"},d={class:"chess-example"},c={class:"chess-figure"};function h(g,e,_,u,x,f){const n=i("ArticleImage");return l(),r("div",null,[e[1]||(e[1]=a('<h1 id="中国象棋-开局原则与常见布局" tabindex="-1">中国象棋：开局原则与常见布局 <a class="header-anchor" href="#中国象棋-开局原则与常见布局" aria-label="Permalink to &quot;中国象棋：开局原则与常见布局&quot;">​</a></h1><p>开局的任务是让车马炮能协同工作，同时保护帅。一个布局名字不是胜利保证；如果对手走法变了，不能继续照抄原来的步骤。</p><h2 id="先看棋子的出路" tabindex="-1">先看棋子的出路 <a class="header-anchor" href="#先看棋子的出路" aria-label="Permalink to &quot;先看棋子的出路&quot;">​</a></h2><p>初始局面里，车被其他棋子限制，马的出口有限，炮已经能横走。优先考虑让马有前进点、让车接通道路，再决定在哪一侧进攻。</p><p>“发展”指把后排棋子调到能影响局面的地方，不是走得越远越好。过早深入的炮，可能受到兵和马的追赶，一连走好几次而其他棋子仍在原地。</p><h2 id="三种常见布局在做什么" tabindex="-1">三种常见布局在做什么 <a class="header-anchor" href="#三种常见布局在做什么" aria-label="Permalink to &quot;三种常见布局在做什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>布局</th><th>第一眼能看到的特点</th><th>新手应该理解的目的</th></tr></thead><tbody><tr><td>中炮</td><td>一炮移到中路</td><td>给中兵和将前区域压力，随后需要出马出车配合</td></tr><tr><td>屏风马</td><td>两马向内发展</td><td>互相协调、照顾中路，不等于一直被动防守</td></tr><tr><td>飞相</td><td>相向中间或侧翼飞起</td><td>加强阵形，耐心发展，不能把“稳”理解为不出车</td></tr></tbody></table><p>先选一种思路练习即可。中炮好理解，但不能认为对方中卒被炮盯着就一定能安全吃掉。</p><h2 id="可在实物棋盘复现的六个回合" tabindex="-1">可在实物棋盘复现的六个回合 <a class="header-anchor" href="#可在实物棋盘复现的六个回合" aria-label="Permalink to &quot;可在实物棋盘复现的六个回合&quot;">​</a></h2>',9)),s("div",d,[s("div",c,[s("p",null,[p(n,{src:"/images/chess/xiangqi-opening.svg",alt:"六回合后 · 双方出子。对照下方着法表；接下来轮红走。"})])]),e[0]||(e[0]=a(`<div class="chess-explanation"><p>坐标仍从红方看：a～i 从左到右，1～10 从下到上。箭头只写起终点，每行红黑各走一步。</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>回合   红方            黑方</span></span>
<span class="line"><span>1      炮 h3→e3        马 h10→g8</span></span>
<span class="line"><span>2      马 h1→g3        马 b10→c8</span></span>
<span class="line"><span>3      车 i1→h1        车 i10→h10</span></span>
<span class="line"><span>4      兵 g4→g5        卒 g7→g6</span></span>
<span class="line"><span>5      马 b1→c3        卒 c7→c6</span></span>
<span class="line"><span>6      车 a1→b1        车 a10→b10</span></span></code></pre></div><p>这是用于观察发展的合法示范线，不是“最佳六步”。第一步红炮平中，黑方出马；第二步后黑双马形成常见的屏风结构。红车第三步利用 h1 已被马腾空而横出。最后双方另一翼的马也已离开底线，另一车可以横移接通道路。</p><p>注意第 4 回合兵卒相对，并不是碰到一起就自动交换；轮到谁、谁能吃、后面谁能接应，都要另外算。</p></div>`,1))]),e[2]||(e[2]=a('<h2 id="为什么不能只顾吃中卒" tabindex="-1">为什么不能只顾吃中卒 <a class="header-anchor" href="#为什么不能只顾吃中卒" aria-label="Permalink to &quot;为什么不能只顾吃中卒&quot;">​</a></h2><p>开局红炮到 e3 后，e4 红兵可以成为炮架，红炮在几何上可能吃到 e7 黑卒。但这只证明走法可能合法，不证明划算。吃完后炮深入黑方，两马、车或士象怎样攻击它？红方是否浪费步数救炮？要把对手的回应写出来再决定。</p><p>一个实用检查顺序是：我有没有被将军；对方刚走的棋攻击了什么；这步是否让新棋子参加战斗；落点能否被直接吃掉。前两项永远比背布局名称重要。</p><h2 id="练习与答案" tabindex="-1">练习与答案 <a class="header-anchor" href="#练习与答案" aria-label="Permalink to &quot;练习与答案&quot;">​</a></h2><ol><li>示例中红车 i1→h1 为什么可行？<strong>原来 h1 的红马已到 g3，落点空且相邻。</strong></li><li>若第一步走的是红兵，第三步还能直接照抄同一线吗？<strong>不一定。</strong> 前提可能不同，要重新检查 h1 是否腾空。</li><li>开局六步都走同一个炮会怎样？<strong>不必然输，但其他棋子没有发展，炮可能孤立。</strong> 请比较双方已经离开初始位置的车马数量。</li></ol><p>下一盘只设一个目标：前十回合尽量让两马和至少一车参与，并在每次吃子前看一次对手的回吃。不要同时背多套变化。</p><p>基本走法核对：<a href="https://www.wxf-xiangqi.org/images/wxf-rules/2018_World_XiangQi_Rules_English2018.pdf" target="_blank" rel="noopener noreferrer">WXF 规则</a>。示范线和学习建议为原创教学设计。</p>',7))])}const q=t(o,[["render",h]]);export{m as __pageData,q as default};
